var a=`1053-nasi-lemak`;var t=`world-1053`;var n=`MY`;var s=`southeast-asia`;var o=8;var r=55;var l={en:`Nasi Lemak`,ua:`Насі лемак`};var d={en:`Nasi Lemak is a dish from Malaysia prepared with jasmine rice, coconut milk, pandan leaves, lemongrass. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Насі лемак, страва кухні країни Малайзія, яку готують із таких продуктів: рис жасмин, кокосове молоко, листя пандану, лемонграс. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 25 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 25 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`jasmine-rice`,430,`g`],[`coconut-milk`,420,`ml`],[`water`,350,`ml`],[`pandan-leaves`,3,`leaf`],[`lemongrass`,1,`pcs`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 8 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 8 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:8,i:[[`dried-anchovies`,75,`g`],[`peanut`,100,`g`],[`canola-oil`,35,`ml`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 9 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 9 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:9,i:[[`red-onion`,160,`g`],[`shrimp-paste`,15,`g`],[`tamarind-concentrate`,35,`g`],[`chili-powder`,10,`g`],[`palm-sugar`,30,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`cucumber`,160,`g`]]}];var m={slug:a,id:t,country:`MY`,region:s,servings:8,minutes:55,title:l,text:d,steps:u};export{n as country,m as default,t as id,r as minutes,s as region,o as servings,a as slug,u as steps,d as text,l as title};